// Produces site/attestation.json — the document the attestation view renders.
// The diff is a pure function over checked-in documents (scripts/attest.mjs), so
// the published verdict is reviewable without nono, without a probe release and
// without running a scan: exactly the point of publishing it this way.
//
// Two ways in. With no arguments the inputs are the checked-in fixtures, so the
// page can be regenerated by anyone with `node scripts/build-attestation.mjs`.
// With --capability-set/--sandbox/--baseline it reads a real run's documents —
// that is how scripts/attest-profile.sh publishes an observed attestation, and it
// takes the profile identifier and the version *actually resolved* as arguments,
// so pointing it at a different registry profile needs no code change.
//
// Either way the `source` field says which it was, on the document itself, so a
// fixture-built page can never be mistaken for an observed run.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { attest } from "./attest.mjs";

const OUT = new URL("../site/attestation.json", import.meta.url);
const fixture = (name) =>
  JSON.parse(readFileSync(new URL(`../tests/fixtures/attestation/${name}.json`, import.meta.url), "utf8"));

const FIXTURE_SOURCE = "tests/fixtures/attestation — checked-in documents, not an observed run";

export function buildAttestation({ profile, capabilitySet, sandbox, baseline, home, source } = {}) {
  return {
    source: source ?? FIXTURE_SOURCE,
    ...attest({
      profile: profile ?? { id: "nolabs-ai/codex", version: "0.4.1" },
      capabilitySet: capabilitySet ?? fixture("capability-set"),
      sandbox: sandbox ?? fixture("report-under-profile"),
      baseline: baseline ?? fixture("report-baseline"),
      home: home ?? "/home/runner",
    }),
  };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const arg = (name) => {
    const i = process.argv.indexOf(`--${name}`);
    return i > 0 ? process.argv[i + 1] : undefined;
  };
  const doc = (name) => (arg(name) ? JSON.parse(readFileSync(arg(name), "utf8")) : undefined);

  const capabilitySet = doc("capability-set");
  // Half a real run is not a run: the diff needs all three documents or none, or
  // it would quietly mix an observed report against a fixture baseline.
  if (capabilitySet && !(arg("sandbox") && arg("baseline") && arg("profile") && arg("version"))) {
    console.error("build-attestation: --capability-set needs --sandbox, --baseline, --profile and --version too");
    process.exit(2);
  }

  const out = arg("out") ?? fileURLToPath(OUT);
  writeFileSync(
    out,
    JSON.stringify(
      buildAttestation({
        profile: arg("profile") ? { id: arg("profile"), version: arg("version") } : undefined,
        capabilitySet,
        sandbox: doc("sandbox"),
        baseline: doc("baseline"),
        home: arg("home"),
        source: capabilitySet ? `observed run under ${arg("profile")}@${arg("version")}` : undefined,
      }),
      null,
      2,
    ) + "\n",
  );
  console.error(`build-attestation: wrote ${out}`);
}
